(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.25)*18 + Math.cos(y*0.013-t*0.18)*12;
  const w1y = Math.cos(y*0.016-t*0.22)*18 + Math.sin(x*0.014+t*0.3)*12;
  const w2x = Math.sin((x+w1x)*0.025-t*0.4)*8 + Math.cos((y+w1y)*0.02+t*0.35)*6;
  const w2y = Math.cos((y+w1y)*0.022+t*0.38)*8 + Math.sin((x+w1x)*0.019-t*0.42)*6;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.85],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.1],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.9],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 1.05],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.95],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+4)*50, 0.11, 2.1, 0.8],
    [400+Math.cos(t*0.55+2)*60, 200+Math.sin(t*0.75+1)*55, 0.085, 2.4, 1.0]
  ];
  let aS=0, iS=0, cS=0;
  for (const [sX,sY,f,sp,w] of src) {
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const wv = Math.sin(d*f-t*sp)*w;
    aS += wv; iS += Math.sin(d*f*0.7+t*sp*0.6+1.5)*w;
    cS += Math.sin(d*f*1.4-t*sp*1.3+2.0)*w*0.5;
  }
  const n = src.length, act=aS/n, inh=iS/n, cross=cS/n;
  const turb1 = (Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2;
  const turb2 = Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2;
  const micro = Math.sin(sx*0.22+t*3)*Math.sin(sy*0.22-t*2.7)*0.15;
  const bg = turb1+turb2+micro;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const sp1=Math.sin(dist*0.05-ang*3-t*1.5), sp2=Math.sin(dist*0.04+ang*4-t*1.2);
  const sp3=Math.sin(dist*0.08-ang*2+t*0.9)*0.3;
  const spiral=(sp1+sp2)*0.4+sp3;
  const lap = Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5;
  const cell=Math.tanh(lap*1.5)*0.3;
  const rd1 = act-inh*0.7+bg*0.3+spiral;
  const rd2 = cross*0.4+Math.sin(act*2.5-inh*1.8+t)*0.3;
  const rd3 = Math.sin(rd1*1.5+rd2*2.0-t*0.5)*0.2;
  const reaction=Math.tanh((rd1+rd2+rd3)*2.2);
  const blend=reaction*0.65+cell*0.2+Math.tanh(rd2)*0.15;
  const v=blend*0.5+0.5;
  const pal=[
    [12,22,78],[18,55,115],[25,95,130],[35,140,135],
    [140,175,80],[200,180,55],[215,130,60],[185,70,65],
    [130,35,75],[70,22,62],[12,22,78]
  ];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const rE=reaction*reaction;
  const lum=0.75+Math.sin(reaction*Math.PI)*0.2+rE*0.05;
  const edge=Math.abs(reaction)>0.65?1.0+Math.abs(reaction)*0.18:1.0;
  const glow=Math.max(0,1-Math.abs(reaction)*1.5)*0.12;
  return [
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+glow*60)|0),
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+glow*80)|0),
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+glow*120)|0)
  ];
}
